SourceCode.Declaration:
/// <summary>
/// Extension for the `EcoResAttributeValue` table that ensures attribute-related product caches are refreshed
/// when specific attribute values change. Provides extension points for future validation and cascading logic
/// related to attribute inserts, updates, and deletes.
/// </summary>
[ExtensionOf(tableStr(EcoResAttributeValue))]
final class EcoResAttributeValue_Metcash_Extension
{
}

Method.Source:
/// <summary>
/// Inserts a new attribute value record and then updates product-level attribute cache if the inserted
/// attribute is one of the configured special attributes.
/// </summary>
public void insert()
{
    next insert();

    this.updateAttributesCacheValue(this.Attribute, this.InstanceValue);
}

/// <summary>
/// Updates an existing attribute value record and refreshes product-level attribute cache when relevant
/// fields change. Retains base update behavior and invokes cache refresh afterwards.
/// </summary>
public void update()
{
    next update();

    this.updateAttributesCacheValue(this.Attribute, this.InstanceValue);
}

/// <summary>
/// Deletes an attribute value record, invoking a cache refresh after performing the base delete.
/// Keeps default delete behavior while providing a single extension point for future checks or cascades.
/// </summary>
public void delete()
{
    RecId savedInstanceValue = this.InstanceValue;
    RecId savedAttribute = this.Attribute;

    next delete();

    // Refresh cache after the delete, using captured values
    this.updateAttributesCacheValue(savedAttribute, savedInstanceValue);
}

/// <summary>
/// Helper that uses provided attribute and instanceValue to perform the refresh. Defensive checks added.
/// </summary>
public void updateAttributesCacheValue(RecId attributeRecId, RecId instanceValue)
{
    METGetAttributeValue        getAttributeValue;
    EcoResProductParameters     ecoResProductParameters = EcoResProductParameters::find();
    RecId                       productRecId;
    InventTable                 inventTable;

    // Quick guard: nothing to do if instanceValue is empty
    if (!instanceValue)
    {
        return;
    }

    // Only act for configured special attributes
    if (attributeRecId == ecoResProductParameters.METConsumerGSTExempt
        || attributeRecId == ecoResProductParameters.METLevyType
        || attributeRecId == ecoResProductParameters.METInvoiceCategory
        || attributeRecId == ecoResProductParameters.METPricedByWeight
        || attributeRecId == ecoResProductParameters.METTempItemForPackChange)
    {
        productRecId = EcoResProductInstanceValue::find(instanceValue).Product;
        if (!productRecId)
        {
            return;
        }

        inventTable = InventTable::findByProduct(productRecId);
        if (!inventTable.RecId)
        {
            return;
        }

        // Perform the attribute sync — keep it in its own transaction.
        ttsbegin;
        getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
        getAttributeValue.setAttributeValues(ecoResProductParameters);
        ttscommit;
    }
}
